"u3.nac": { task: "Choose the right form.", hint: "-o → -a, -ês → -esa, -ol → -ola/-óis, -ão → -ã/-ães. Mixed group → masculine plural. Lowercase!", quiz2: [
  { q: "A Aiko e a Yui são…", opts: ["japonesas", "japoneses", "japonesa"], why: "Two women → feminine plural." },
  { q: "O Pedro e a Ana são…", opts: ["portugueses", "portuguesas", "português"], why: "Mixed → masculine plural." },
  { q: "Plural of “alemão”:", opts: ["alemães", "alemãos", "alemões"], why: "alemão → alemães." },
  { q: "Find the mistake: “Ela é Inglesa.”", opts: ["Lowercase: inglesa", "It should be “inglês”", "No mistake"], why: "Nationalities are lowercase." },
  { q: "Ireland → Irish (man):", opts: ["irlandês", "irlando", "irlandesa"], why: "-ês for him, -esa for her." },
  { q: "Os pais da Eva são da Bélgica. São…", opts: ["belgas", "belgos", "belgues"], why: "belga → belgas." },
]},
"u3.linguas": { task: "Choose the right form of the verb.", hint: "-ar verbs: -o, -as, -a, -amos, -am. falar, morar, ficar. um pouco de + language.", quiz2: [
  { q: "A minha mãe ___ em Coimbra. (morar)", opts: ["mora", "moro", "moram"], why: "ela → mora." },
  { q: "Tu ___ espanhol? (falar)", opts: ["falas", "fala", "falo"], why: "tu → falas." },
  { q: "O Tom e eu ___ inglês. (falar)", opts: ["falamos", "falam", "falo"], why: "Tom + eu = nós → falamos." },
  { q: "Que língua falam os angolanos?", opts: ["Português.", "Angolano.", "Espanhol."], why: "Portuguese is Angola's official language." },
  { t: "order", q: "Put the words in order: “I speak a little German.”", a: ["Falo", "um", "pouco", "de", "alemão."], why: "um pouco de + language." },
  { q: "“Ela só fala russo” means…", opts: ["She only speaks Russian.", "She speaks Russian well.", "She also speaks Russian."], why: "só = only." },
]},
"u3.estar": { task: "Choose ser or estar.", hint: "ser = permanent (origin, nationality, where a city is). estar = now (where you are now, how you feel).", quiz2: [
  { q: "O Marco ___ italiano.", opts: ["é", "está"], why: "Nationality → ser." },
  { q: "Hoje o Marco ___ em Paris.", opts: ["está", "é"], why: "Right now → estar." },
  { q: "Nós ___ em casa agora.", opts: ["estamos", "somos", "estão"], why: "Location now → estar, nós → estamos." },
  { q: "Onde ___ Faro?", opts: ["é", "está", "estás"], why: "A city's place → ser (or fica)." },
  { q: "Find the mistake: “Sou bem, obrigada.”", opts: ["How you feel → Estou bem.", "It should be “É bem.”", "No mistake."], why: "Feeling now → estar." },
  { q: "Liu is Chinese, lives in Lisbon, is in Madrid this week:", opts: ["O Liu é chinês, mora em Lisboa e esta semana está em Madrid.", "O Liu está chinês, é em Lisboa e esta semana mora em Madrid.", "O Liu é chinês, está em Lisboa e esta semana é em Madrid."], why: "é (origin) · mora (lives) · está (now)." },
]},
"u3.num1000": { task: "", hint: "100 = cem, 101+ = cento e… 500 = quinhentos. Put e between every part.", quiz2: [
  { q: "Listen. Which number?", say: "novecentos e sessenta e dois", opts: ["962", "972", "862"], why: "novecentos (900) + sessenta (60) + dois." },
  { q: "Listen. Which number?", say: "cento e quarenta e um", opts: ["141", "241", "114"], why: "cento = 100 + something." },
  { q: "Listen. Which number?", say: "setecentos e setenta e sete", opts: ["777", "767", "677"], why: "sete everywhere: 700 + 70 + 7." },
  { q: "How do you write 450?", opts: ["quatrocentos e cinquenta", "quatrocentos cinquenta", "quatro cem e cinquenta"], why: "e between the parts." },
  { q: "A bag costs 200 euros:", opts: ["duzentos euros", "dois cem euros", "doiscentos euros"], why: "200 = duzentos." },
]},
"u3.pron3": { task: "", hint: "ão = “owng” (masculine), ã = “ahn” (feminine). S between vowels = Z.", quiz2: [
  { q: "Listen. Which word?", say: "alemã", opts: ["alemã", "alemão"], why: "Short nasal “ahn” = alemã." },
  { q: "Listen. Which word?", say: "irmão", opts: ["irmão", "irmã"], why: "“owng” = irmão." },
  { q: "Stressed syllable in “japonês”:", opts: ["NÊS", "JA", "PO"], why: "Accent marks the stress." },
  { q: "S in “japonesa” sounds like…", opts: ["z", "s", "sh"], why: "Between vowels = z." },
]},
