"u4.objetos": { task: "Choose the right word.", hint: "Masculine usually -o, -l, -r, -s, -ão. Feminine usually -a. Traps: o dia, o mapa. Plural: -s, -es, -l → -is, -m → -ns, -ão → -ões/-ães/-ãos.", quiz2: [
  { q: "___ dia", opts: ["um", "uma"], why: "Trap word: o dia." },
  { q: "___ viagem", opts: ["uma", "um"], why: "a viagem (trip) is feminine." },
  { q: "Plural of “a mão”:", opts: ["as mãos", "as mães", "as mões"], why: "mão → mãos." },
  { q: "Plural of “o cão”:", opts: ["os cães", "os cãos", "os cões"], why: "cão → cães." },
  { q: "Plural of “um lápis”:", opts: ["lápis", "lápises", "lápiss"], why: "Doesn't change." },
  { q: "Plural of “a viagem”:", opts: ["as viagens", "as viagems", "as viagemes"], why: "-m → -ns." },
]},
"u4.isto": { task: "Choose isto, isso or aquilo.", hint: "isto = near me · isso = near you · aquilo = far from both.", quiz2: [
  { q: "On a call, your friend says “I'm holding something red”. You ask: “O que é ___?”", opts: ["isso", "isto", "aquilo"], why: "It's near the listener → isso." },
  { q: "A plane is far in the sky: “O que é ___?”", opts: ["aquilo", "isso", "isto"], why: "Far from both → aquilo." },
  { q: "You show your new phone: “___ é o meu telemóvel novo.”", opts: ["Isto", "Isso", "Aquilo"], why: "In your hand → isto." },
  { t: "order", q: "Put the words in order: “How do you say this in Portuguese?”", a: ["Como", "se", "diz", "isto", "em", "português?"], why: "Como se diz isto em português?" },
  { q: "“O que é aquilo?” — best answer:", opts: ["É um relógio.", "Sou um relógio.", "Está um relógio."], why: "Identifying a thing → é." },
]},
"u4.cores": { task: "Choose the right form.", hint: "-o colours change (branco/branca/brancos/brancas). verde → verdes. azul → azuis. cor-de-rosa never changes. Colour after the noun.", quiz2: [
  { q: "As paredes são ___ (yellow).", opts: ["amarelas", "amarelos", "amarela"], why: "as paredes → amarelas." },
  { q: "Os carros são ___ (pink).", opts: ["cor-de-rosa", "cor-de-rosas", "rosas"], why: "cor-de-rosa never changes." },
  { q: "A bandeira da Irlanda é verde, branca e…", opts: ["cor de laranja", "vermelha", "amarela"], why: "Green, white and orange." },
  { q: "Find the mistake: “Tenho uma azul mochila.”", opts: ["Colour after the noun: uma mochila azul", "It should be “azula”", "No mistake"], why: "Adjective after the noun." },
  { q: "Os gatos são ___ (black).", opts: ["pretos", "pretas", "preto"], why: "os gatos → pretos." },
  { q: "É o computador ___ Rui.", opts: ["do", "da", "de"], why: "o Rui → do Rui." },
]},
"u4.aula": { task: "Choose the best phrase.", hint: "Não percebo = I don't understand. Pode repetir? Como se escreve…? O que significa…? Qual é a página?", quiz2: [
  { q: "You don't know a word in the text. You ask:", opts: ["O que significa esta palavra?", "Como se diz esta palavra?", "Pode fechar o livro?"], why: "significa = means." },
  { q: "The teacher writes too fast. You ask her:", opts: ["Pode escrever no quadro outra vez?", "Pode ler o texto?", "Qual é o seu nome?"], why: "Ask to write it again on the board." },
  { q: "You missed the page number:", opts: ["Qual é a página?", "Onde é a página?", "Quanto é a página?"], why: "Qual é a página?" },
  { q: "The teacher says “Ouçam e repitam”. You…", opts: ["listen and repeat", "read and write", "work in pairs"], why: "ouvir = to listen, repetir = to repeat." },
  { q: "The teacher says “Não escrevam”. You…", opts: ["don't write", "write it down", "don't speak"], why: "escrever = to write." },
]},
"u4.pron4": { task: "", hint: "Yes/no questions = same words, voice goes up. Unstressed E almost disappears.", quiz2: [
  { q: "Listen. Statement or question?", say: "Eles falam francês.", opts: ["Statement", "Question"], why: "The voice goes down at the end." },
  { q: "Listen. Statement or question?", say: "Elas moram em Roma?", opts: ["Question", "Statement"], why: "The voice goes up at the end." },
  { q: "The final E in “nome” sounds like…", opts: ["almost nothing", "ay", "ee"], why: "NOM." },
  { q: "Which E is pronounced [ɨ] (almost silent)?", opts: ["the last E in “sete”", "the É in “é”", "the first E in “sete”"], why: "Unstressed final E." },
]},
