"u5.ter": { task: "Choose the right form.", hint: "ter: tenho, tens, tem, temos, têm. Answer with the verb: Tenho. / Não tenho. Type of thing: de (garrafa de água). Owner: do/da.", quiz2: [
  { q: "A Rita e o Luís ___ dois carros.", opts: ["têm", "tem", "temos"], why: "They → têm." },
  { q: "“Têm passaporte?” — “Sim, ___.” (nós)", opts: ["temos", "têm", "tenho"], why: "Answer for nós → temos." },
  { q: "___ cigarros? (tu)", opts: ["Tens", "Tem", "Tenho"], why: "tu → tens." },
  { q: "a carteira ___ Mafalda", opts: ["da", "de", "do"], why: "Owner → da Mafalda." },
  { q: "uma chávena ___ café (a cup of coffee)", opts: ["de", "do", "da"], why: "Type/content → de." },
  { q: "___ moedas", opts: ["duas", "dois"], why: "a moeda → duas." },
]},
"u5.ondeesta": { task: "Choose the right word.", hint: "Now → estar. em casa (no article). no carro, na rua. é que after a question word.", quiz2: [
  { q: "A Sara ___ no escritório agora.", opts: ["está", "é", "tem"], why: "Now → estar." },
  { q: "Os meninos estão ___ escola.", opts: ["na", "no", "em"], why: "a escola → na." },
  { q: "Find the mistake: “Ela está na casa.”", opts: ["“At home” has no article: em casa", "It should be “no casa”", "No mistake"], why: "Estou em casa." },
  { q: "Rewrite with é que: “Quem tem as chaves?”", opts: ["Quem é que tem as chaves?", "É que quem tem as chaves?", "Quem tem é que as chaves?"], why: "Question word + é que." },
  { t: "order", q: "Put the words in order: “Where is my wallet?”", a: ["Onde", "está", "a", "minha", "carteira?"], why: "Onde está a minha carteira?" },
]},
"u5.possessivos": { task: "Choose the right possessive.", hint: "Agrees with the thing: o meu / a minha, o teu / a tua, o seu / a sua, o nosso / a nossa. His/her/their after the noun: dele, dela, deles.", quiz2: [
  { q: "Ana, ___ chave está aqui. (your, tu)", opts: ["a tua", "o teu", "tua"], why: "a chave → a tua." },
  { q: "O Pedro? O telemóvel ___ está no carro.", opts: ["dele", "dela", "seu"], why: "His → dele." },
  { q: "A Rita? Os óculos ___ são caros.", opts: ["dela", "dele", "deles"], why: "Her → dela." },
  { q: "Somos espanhóis. ___ cidade é Sevilha.", opts: ["A nossa", "O nosso", "Nossa"], why: "a cidade → a nossa." },
  { q: "Find the mistake: “Meu carro é branco.”", opts: ["Needs the article: O meu carro", "It should be “Minha carro”", "No mistake"], why: "In Portugal: o meu carro." },
  { q: "Senhor Costa, ___ passaporte, faz favor. (formal)", opts: ["o seu", "o teu", "a sua"], why: "Formal you → o seu." },
]},
"u5.aqui": { task: "Choose aqui, aí or ali.", hint: "aqui = here, near me (isto) · aí = near you (isso) · ali = over there (aquilo).", quiz2: [
  { q: "On the phone: “Está calor ___ em Lisboa?”", opts: ["aí", "aqui", "ali"], why: "Where the listener is → aí." },
  { q: "“Vem ___!” (Come here!)", opts: ["aqui", "aí", "ali"], why: "Near the speaker → aqui." },
  { q: "Pointing at a far café: “O café é ___.”", opts: ["ali", "aí", "aqui"], why: "Far from both → ali." },
  { q: "Isso ___ é teu?", opts: ["aí", "aqui", "ali"], why: "isso ↔ aí." },
]},
"u5.pron5": { task: "", hint: "Strong R: start of word and RR. Soft R: between vowels and before consonants. -em = nasal “ayng”.", quiz2: [
  { q: "Listen. Which word?", say: "sem", opts: ["sem", "cem", "quem"], why: "sem = without." },
  { q: "Which word has the strong R?", opts: ["Inglaterra", "porta", "carta"], why: "RR = strong." },
  { q: "Which word has the soft R?", opts: ["estar", "rua", "Roma"], why: "Final R = soft tap." },
  { q: "Listen. Which word?", say: "relógio", opts: ["relógio", "elógio"], why: "Strong R at the start." },
]},
