"u6.profissoes": { task: "Choose the right form.", hint: "-o → -a, -or → -ora, ator → atriz. -e and -ista don't change. No article: Sou médica.", quiz2: [
  { q: "Feminine of “cantor”:", opts: ["cantora", "cantriz", "cantor"], why: "-or → -ora." },
  { q: "Feminine of “jornalista”:", opts: ["jornalista", "jornalisto", "jornalistra"], why: "-ista doesn't change." },
  { q: "Find the mistake: “Ela é uma enfermeira.”", opts: ["No article with jobs: Ela é enfermeira.", "It should be “enfermeiro”", "No mistake"], why: "Sou / é + job, no article." },
  { q: "Masculine of “empregada”:", opts: ["empregado", "empregador", "empregada"], why: "-a → -o." },
  { q: "Who works at night in a hospital?", opts: ["Uma enfermeira.", "Uma atriz.", "Uma advogada."], why: "enfermeira = nurse." },
]},
"u6.soletrar": { task: "", hint: "Letter names: á, bê, cê, dê, é, efe, gê, agá, i, jota, capa, ele, eme, ene, ó, pê, quê, erre, esse, tê, u, vê, dâblio, xis, ípsilon, zê.", quiz2: [
  { q: "Listen to the spelling. Which acronym?", say: "u, esse, bê", opts: ["USB", "OSB", "USP"], why: "u = U, esse = S, bê = B." },
  { q: "Listen to the spelling. Which acronym?", say: "bê, eme, dâblio", opts: ["BMW", "BMV", "VMW"], why: "dâblio = W." },
  { q: "Listen to the spelling. Which surname?", say: "esse, i, ele, vê, á", opts: ["Silva", "Silba", "Selva"], why: "S-I-L-V-A." },
  { q: "How do you spell “Hugo”?", opts: ["agá, u, gê, ó", "á, u, jota, ó", "agá, u, quê, ó"], why: "H = agá, G = gê." },
]},
"u6.andar": { task: "", hint: "1.º primeiro … 10.º décimo. R/C = ground floor, Esq. = left, Dto. = right. Ordinals before the noun.", quiz2: [
  { q: "Antonio lives in “3.º Dto.”:", opts: ["3rd floor, right", "3rd floor, left", "13th floor"], why: "Dto. = direito." },
  { q: "Em que andar mora a Oxana (4.º Esq.)?", opts: ["No quarto andar.", "No quatro andar.", "Na quarta andar."], why: "4th = quarto, o andar → no." },
  { q: "The 6th floor:", opts: ["o sexto andar", "o seis andar", "o sétimo andar"], why: "6th = sexto." },
  { q: "Put in order: “o / último / nome”", opts: ["o último nome", "o nome último", "último o nome"], why: "Ordinal-like words go before the noun." },
  { q: "“Moro no rés do chão” means…", opts: ["I live on the ground floor.", "I live on the top floor.", "I live on the street."], why: "R/C = rés do chão." },
]},
"u6.dados": { task: "Choose the right word.", hint: "Age = ter + anos. quanto/quanta/quantos/quantas agrees with the noun. apelido = surname.", quiz2: [
  { q: "___ malas tem a Ana?", opts: ["Quantas", "Quantos", "Quanta"], why: "as malas → quantas." },
  { q: "___ lápis tem o Pedro?", opts: ["Quantos", "Quantas", "Quanto"], why: "o lápis (masculine) → quantos." },
  { q: "How old are you? (formal)", opts: ["Que idade tem?", "Quantos anos é?", "Qual é a sua idade tens?"], why: "Que idade tem? = Quantos anos tem?" },
  { q: "“Qual é o seu estado civil?” — answer:", opts: ["Sou solteira.", "Tenho 30 anos.", "Sou de Lisboa."], why: "Estado civil = single/married." },
  { q: "Read the e-mail aloud: ana.lopes@gmail.com", opts: ["ana ponto lopes arroba gmail ponto com", "ana ponto lopes ponto gmail arroba com", "ana lopes at gmail dot com"], why: "@ = arroba, . = ponto." },
  { t: "order", q: "Put the words in order: “What's your full name?” (formal)", a: ["Qual", "é", "o", "seu", "nome", "completo?"], why: "completo goes after the noun." },
]},
"u6.pron6": { task: "", hint: "en-/em- at the start: nasal. SS = s. S: start = s, between vowels = z, end = sh.", quiz2: [
  { q: "S in “brasileiro” is…", opts: ["[z]", "[s]", "[ʃ]"], why: "Between vowels → z." },
  { q: "S in “país” is…", opts: ["[ʃ]", "[z]", "[s]"], why: "End of word → sh." },
  { q: "Which word starts with a nasal vowel?", opts: ["empresário", "escola", "Europa"], why: "em- + consonant = nasal." },
  { q: "SS in “passaporte” is…", opts: ["[s]", "[z]"], why: "SS is always s." },
]},
