"u7.adjetivos": { task: "", hint: "bonito↔feio, bom↔mau, novo↔velho, grande↔pequeno, rico↔pobre, caro↔barato, antigo↔moderno, simpático↔antipático. perto↔longe.", quiz2: [
  { q: "Opposite of “moderno”:", opts: ["antigo", "novo", "pobre"], why: "moderno ↔ antigo." },
  { q: "Opposite of “rico”:", opts: ["pobre", "barato", "pequeno"], why: "rico ↔ pobre." },
  { q: "A watch for €2500 is…", opts: ["caro", "barato", "pobre"], why: "Expensive → caro." },
  { q: "Your grandfather's 1970 car is…", opts: ["velho", "antigo", "moderno"], why: "Old and worn → velho." },
  { q: "The beach is 200 m from the hotel. It's…", opts: ["perto", "longe", "fora"], why: "200 m = near." },
]},
"u7.concordancia": { task: "Choose the right form.", hint: "Adjectives agree and go after the noun. bom/boa/bons/boas, mau/má/maus/más. -il → -eis. muito/bastante before the adjective.", quiz2: [
  { q: "As casas são muito ___.", opts: ["bonitas", "bonitos", "bonita"], why: "as casas → bonitas." },
  { q: "Uma notícia ___ (a bad piece of news)", opts: ["má", "mau", "mal"], why: "a notícia → má." },
  { q: "Os exames são ___.", opts: ["difíceis", "difícils", "difíciles"], why: "-il → -eis." },
  { q: "As pessoas são ___.", opts: ["agradáveis", "agradávels", "agradáveles"], why: "-el → -eis." },
  { q: "Find the mistake: “Lisboa é uma bonita muito cidade.”", opts: ["Lisboa é uma cidade muito bonita.", "Lisboa é muito uma cidade bonita.", "No mistake"], why: "noun + muito + adjective." },
  { t: "order", q: "Put the words in order: “The hotels are quite cheap.”", a: ["Os", "hotéis", "são", "bastante", "baratos."], why: "bastante before the adjective." },
]},
"u7.gostar": { task: "Choose the right word.", hint: "gostar DE. de + o = do, de + a = da. de + isto = disto, de + isso = disso, de + aqui = daqui. Porquê? — Porque…", quiz2: [
  { q: "Gosto ___ chá.", opts: ["de", "do", "da"], why: "chá in general → de chá." },
  { q: "A Inês gosta ___ Paris.", opts: ["de", "da", "do"], why: "Cities have no article → de." },
  { q: "Vocês gostam ___ Brasil?", opts: ["do", "de", "da"], why: "o Brasil → do." },
  { q: "Não gosto ___. (aquilo)", opts: ["daquilo", "de aquilo", "aquilo"], why: "de + aquilo = daquilo." },
  { q: "Find the mistake: “Eu gosto Portugal.”", opts: ["gostar needs de: Gosto de Portugal.", "It should be “Eu gosta Portugal”", "No mistake"], why: "Always gostar de." },
  { t: "order", q: "Put the words in order: “Why don't you like your house?”", a: ["Porque", "é", "que", "não", "gostas", "da", "tua", "casa?"], why: "Porque é que…? = Why…?" },
]},
"u7.cidades": { task: "", hint: "Macau: rica, moderna, quarto grande e bonito. Ouro Preto: antiga, pequena, bonita; hotel velho, feio, barato, fora do centro.", quiz2: [
  { q: "Which city is modern?", opts: ["Macau", "Ouro Preto"], why: "“Macau é uma cidade rica e muito moderna.”" },
  { q: "Song's hotel is…", opts: ["cheap but ugly", "expensive and modern", "big and pretty"], why: "“velho e bastante feio, mas também muito barato”." },
  { q: "Where is the historic centre “lindo, lindo, lindo”?", opts: ["Ouro Preto", "Macau"], why: "Song's post." },
  { q: "“bastante pequena” means…", opts: ["quite small", "very big", "too small"], why: "bastante = quite." },
]},
"u7.pron7": { task: "", hint: "Final Z = SH. CH = SH. ão / ã / am = nasal. au, á = not nasal.", quiz2: [
  { q: "Listen. Which word?", say: "mão", opts: ["mão", "mau", "má"], why: "Nasal → mão (hand)." },
  { q: "Listen. Which word?", say: "pá", opts: ["pá", "pão", "pau"], why: "Open “ah”, not nasal → pá." },
  { q: "Z in “atriz” sounds like…", opts: ["sh", "z"], why: "Final Z = sh." },
  { q: "Which word has the SH sound?", opts: ["ficha", "fica", "figo"], why: "CH = SH." },
]},
