"u9.familia": { task: "", hint: "os pais = parents, os filhos = children, os irmãos = siblings, os avós = grandparents. avô (ô) = grandpa, avó (ó) = grandma.", quiz2: [
  { q: "O irmão do meu pai é o meu…", opts: ["tio", "primo", "avô"], why: "Father's brother = uncle." },
  { q: "A mãe do meu marido é a minha…", opts: ["sogra", "tia", "avó"], why: "Important box: a sogra." },
  { q: "O filho da minha irmã é o meu…", opts: ["sobrinho", "primo", "neto"], why: "sobrinho = nephew. (New word!)" },
  { q: "“Tenho dois filhos: um rapaz e uma rapariga.” How many daughters?", opts: ["One", "Two", "None"], why: "rapariga = girl → one daughter." },
  { q: "Verónica says “Os meus pais são o Fernando e a Rita.” Pais here means…", opts: ["parents", "fathers", "countries"], why: "os pais = mum + dad." },
  { q: "Bernardo: “Tenho uma irmã.” Is he an only child (filho único)?", opts: ["No", "Yes"], why: "He has a sister." },
]},
"u9.poss2": { task: "Choose the right possessive.", hint: "Plural: os meus / as minhas, os teus / as tuas, os nossos / as nossas. dele/dela/deles don't change.", quiz2: [
  { q: "Plural: “Esta é a tua irmã.” →", opts: ["Estas são as tuas irmãs.", "Estes são os tuas irmãs.", "Estas são as tua irmãs."], why: "Everything goes plural." },
  { q: "Plural: “Esse é o nosso chefe.” →", opts: ["Esses são os nossos chefes.", "Esses são os nosso chefes.", "Essas são as nossas chefes."], why: "Caderno D, 4." },
  { q: "His parents:", opts: ["os pais dele", "os seus pais dele", "os dele pais"], why: "dele after the noun." },
  { q: "___ avós moram em Faro. (our)", opts: ["Os nossos", "As nossas", "Os nosso"], why: "os avós → os nossos." },
  { t: "order", q: "Put the words in order: “Her cousins are very nice.”", a: ["As", "primas", "dela", "são", "muito", "simpáticas."], why: "dela after the noun." },
]},
"u9.este": { task: "Choose este, esse or aquele (right form).", hint: "este/esta/estes/estas = near me · esse/essa/esses/essas = near you · aquele/aquela/aqueles/aquelas = far.", quiz2: [
  { q: "On the photo in your hand: “___ são as minhas primas.”", opts: ["Estas", "Estes", "Essas"], why: "Near me + as primas → estas." },
  { q: "Far away on a hill: “De quem é ___ casa?”", opts: ["aquela", "essa", "esta"], why: "Far + a casa → aquela." },
  { q: "Your friend shows a book: “___ livro é muito interessante.”", opts: ["Esse", "Este", "Aquele"], why: "Near the listener → esse." },
  { q: "“Ela ___ em Coimbra agora.”", opts: ["está", "esta"], why: "is → está (with accent)." },
  { q: "“___ é a minha mãe.” (in the photo you're holding)", opts: ["Esta", "Está", "Esse"], why: "this → esta (no accent)." },
]},
"u9.pron9": { task: "", hint: "L vs LH (= ly). país (2 syllables, country) vs pais (1 syllable, parents). avó open, avô closed.", quiz2: [
  { q: "Listen. Which word?", say: "velho", opts: ["velho", "velo"], why: "LH = ly: VEH-lyoo." },
  { q: "Listen. Which word?", say: "pais", opts: ["pais (parents)", "país (country)"], why: "One syllable = pais." },
  { q: "Listen. Which word?", say: "avô", opts: ["avô", "avó"], why: "Closed “oh” = avô." },
  { q: "In which word is the L different?", opts: ["mulher", "aquele", "lindo"], why: "mulher has LH (Caderno H)." },
]},
